import { createServer, type Socket } from 'node:net';

createServer((socket: Socket): void => {            // handler registered with the loop for this handle
  socket.setEncoding('utf8');
  socket.on('data', (chunk: string): void => { socket.write(chunk); });
}).listen(8080);                                     // libuv demultiplexes; this code never loops
